    active={x["name"]:x for x in active_vaults if isinstance(x,dict) and isinstance(x.get("name"),str)}
    deleted={x["name"]:x for x in deleted_vaults if isinstance(x,dict) and isinstance(x.get("name"),str)}
    if requested_name in active:return {"state":"active_name_conflict","action":"inspect the active vault and confirm its owner; do not delete it to clear a create error"}
    if requested_name not in deleted:return {"state":"no_name_conflict_in_supplied_inventory","action":"recheck subscription, region, permissions and authoritative deleted-vault inventory"}
    record=deleted[requested_name]
    if record.get("purgeProtection") is True:
        return {"state":"soft_deleted_purge_protected","action":"recover the deleted vault if its data is needed; otherwise wait for the retention period to expire; do not attempt purge bypass"}
    return {"state":"soft_deleted_recoverable","action":"restore the vault if it is the intended resource; purge only after explicit owner approval and data-retention review"}
